begin;
with j as (select * from jsonb_to_recordset($law7d0005$[{"code_id":"APK_RF","article_number":"229","version_date":"2002-07-24","article_text":"Принятая по результатам рассмотрения дела резолютивная часть решения размещается в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" не позднее следующего дня после дня ее принятия. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nРешения по делам, возникшим из административных и иных публичных правоотношений и рассматриваемым в порядке упрощенного производства, принимаются арбитражным судом по правилам, предусмотренным статьями 201, 206, 211 и 216 настоящего Кодекса.\n\nЗаявление о составлении мотивированного решения арбитражного суда может быть подано в течение пяти дней со дня размещения решения, принятого в порядке упрощенного производства, в установленном порядке в информационно-телекоммуникационной сети \"Интернет\". В этом случае арбитражным судом решение принимается по правилам, установленным главой 20 настоящего Кодекса, если иное не вытекает из особенностей, установленных настоящей главой. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nМотивированное решение арбитражного суда изготавливается в течение пяти дней со дня поступления от лица, участвующего в деле, соответствующего заявления или со дня подачи апелляционной жалобы. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\nЕсли судья, подписавший резолютивную часть решения, отсутствует в день поступления заявления о составлении мотивированного решения или апелляционной жалобы, вопрос о составлении мотивированного решения указанным судьей разрешается в пятидневный срок, начинающий исчисляться с момента возобновления исполнения указанным судьей своих обязанностей. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\nВ случае составления мотивированного решения арбитражного суда такое решение вступает в законную силу по истечении срока, установленного для подачи апелляционной жалобы.\n\nВ случае подачи апелляционной жалобы решение арбитражного суда первой инстанции, если оно не отменено или не изменено, вступает в законную силу со дня принятия постановления арбитражным судом апелляционной инстанции.\n\nЭто решение, если оно было предметом рассмотрения в арбитражном суде апелляционной инстанции или если арбитражный суд апелляционной инстанции отказал в восстановлении пропущенного срока подачи апелляционной жалобы, и постановление арбитражного суда апелляционной\n\nинстанции, принятое по данному делу, могут быть обжалованы в арбитражный суд кассационной инстанции по основаниям, предусмотренным частью 3 статьи 2882 настоящего Кодекса. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n(Статья в редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n(Дополнение главой - Федеральный закон от 02.03.2016 № 47-ФЗ)","article_title":"Статья 229. Решение по делу, рассматриваемому в порядке упрощенного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fa6dd8bb06ae8e598b4489a0fcbd8ca10eadbc9c9f0ee673679481ed20f4483b"},{"code_id":"APK_RF","article_number":"229.1","version_date":"2002-07-24","article_text":"1. Судебный приказ - судебный акт, вынесенный судьей единолично на основании заявления о взыскании денежных сумм по требованиям взыскателя, предусмотренным статьей 2292 настоящего Кодекса.\n\n2. Судебный приказ является одновременно исполнительным документом и приводится в исполнение в порядке, установленном для исполнения судебных решений.","article_title":"Статья 229.1. Судебный приказ","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4016b378c79ad60c66f4b680744f97be30a91d63bfe756969207d06a8edabaa"},{"code_id":"APK_RF","article_number":"229.2","version_date":"2002-07-24","article_text":"Судебный приказ выдается по делам, в которых:\n\n1) требования вытекают из неисполнения или ненадлежащего исполнения договора и основаны на представленных взыскателем документах, устанавливающих денежные обязательства, если цена заявленных требований не превышает семьсот пятьдесят тысяч рублей; (В редакции  федеральных законов от 28.11.2018 № 451-ФЗ, от 25.12.2023 № 667-ФЗ)\n\n2) требование основано на совершенном нотариусом протесте векселя в неплатеже, неакцепте и недатировании акцепта, если цена заявленного требования не превышает семьсот пятьдесят тысяч рублей; (В редакции  федеральных законов от 28.11.2018 № 451-ФЗ, от 25.12.2023 № 667-ФЗ)\n\n3) заявлено требование о взыскании обязательных платежей и санкций, если указанный в заявлении общий размер подлежащей взысканию денежной суммы не превышает сто тысяч рублей.","article_title":"Статья 229.2. Дела приказного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"19a18cd8982c3bbbe4068a7c81ca8419b0bc7893d8cc945a8d8bd1e7110382a1"},{"code_id":"APK_RF","article_number":"229.3","version_date":"2002-07-24","article_text":"1) наименование арбитражного суда, в который подается заявление;\n\n2) сведения о взыскателе: для взыскателя-гражданина - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, серия и номер водительского удостоверения), для взыскателя-организации - наименование, адрес, идентификационный номер налогоплательщика, реквизиты банковского или казначейского счета и другие необходимые реквизиты; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n3) сведения о должнике: для гражданина-должника - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, место работы (если известно), один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, основной государственный регистрационный номер индивидуального предпринимателя, серия и номер водительского удостоверения); для организации-должника - наименование, адрес, идентификационный номер налогоплательщика и основной государственный регистрационный номер; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n4) требования взыскателя, в том числе период, за который образовалась взыскиваемая задолженность по обязательствам, предусматривающим исполнение по частям или в виде периодических платежей, размер денежной суммы, составляющей платеж, и ее расчет, а также обстоятельства, на которых основаны указанные требования; (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n5) документы, подтверждающие обоснованность требования взыскателя;\n\n6) перечень прилагаемых документов.","article_title":"Статья 229.3. Форма и содержание заявления о выдаче судебного приказа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"34fd3a1965b648039047a595966044d8fc0715bc45041e4b1e40c09324163913"},{"code_id":"APK_RF","article_number":"229.4","version_date":"2002-07-24","article_text":"1. Арбитражный суд возвращает заявление о выдаче судебного приказа в случае нарушения требований к форме и содержанию заявления о выдаче судебного приказа, установленных статьей 2293 настоящего Кодекса, а также в случаях, если:\n\n1) дело неподсудно данному арбитражному суду;\n\n2) не представлены документы, подтверждающие обоснованность требования взыскателя;\n\n3) отклонено ходатайство о предоставлении отсрочки, рассрочки уплаты государственной пошлины или об уменьшении ее размера;\n\n4) от взыскателя поступило ходатайство о возвращении заявления о выдаче судебного приказа.\n\n2. Возвращение заявления о выдаче судебного приказа не является препятствием для повторного обращения взыскателя в арбитражный суд с заявлением к тому же должнику, с тем же требованием и по тем же основаниям после устранения допущенного нарушения.\n\n3. Арбитражный суд отказывает в принятии заявления о выдаче судебного приказа по основаниям, предусмотренным статьей 1271 настоящего Кодекса, а также в случаях, если:\n\n1) заявлено требование, не предусмотренное статьей 2292 настоящего Кодекса;\n\n2) место жительства или место нахождения должника находится вне пределов Российской Федерации;\n\n3) из заявления о выдаче судебного приказа и приложенных к нему документов усматривается наличие спора о праве.\n\n4. О возвращении заявления о выдаче судебного приказа или об отказе в его принятии арбитражный суд в течение трех дней со дня поступления этого заявления в суд выносит определение, которое может быть обжаловано.\n\n(Статья в редакции Федерального закона от 19.12.2016 № 435-ФЗ)","article_title":"Статья 229.4. Основания для возвращения заявления о выдаче судебного приказа или отказа в его принятии","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8ce529ea10083e7ac024946d814466ec80d167bdd82fe96af7c2af341c67ad26"},{"code_id":"APK_RF","article_number":"229.5","version_date":"2002-07-24","article_text":"1. Заявление по делам приказного производства подается в арбитражный суд по общим правилам подсудности, установленным настоящим Кодексом.\n\n2. Судебный приказ по делам приказного производства выносится арбитражным судом в течение десяти дней со дня поступления заявления о выдаче судебного приказа в арбитражный суд.\n\nСудебный приказ выносится без вызова взыскателя и должника и без проведения судебного разбирательства.\n\nСуд исследует изложенные в направленном взыскателем заявлении о выдаче судебного приказа и приложенных к нему документах сведения в обоснование позиции данного лица и выносит судебный приказ на основании представленных документов.\n\nКопия судебного приказа на бумажном носителе в пятидневный срок со дня вынесения судебного приказа высылается должнику, который в течение десяти дней со дня ее получения вправе представить возражения относительно исполнения судебного приказа.\n\nСудебный приказ размещается в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" не позднее следующего дня после дня его вынесения. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nВ определении суда об отмене судебного приказа указывается, что заявленное взыскателем требование может быть предъявлено в порядке искового производства либо производства по делам, возникающим из административных и иных публичных правоотношений.\n\nКопии определения суда об отмене судебного приказа направляются взыскателю и должнику в срок, не превышающий пяти дней со дня вынесения указанного определения. Указанное определение размещается в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" не позднее следующего дня после дня его вынесения. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nО возвращении документов, содержащих возражения должника, суд выносит определение.\n\nСудебный приказ может быть направлен судом для исполнения в форме электронного документа, подписанного судьей усиленной квалифицированной электронной подписью в порядке, установленном законодательством Российской Федерации.\n\n(Статья в редакции Федерального закона от 23.06.2016 № 220-ФЗ)","article_title":"Статья 229.5. Порядок приказного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c373df54377007475b696404da3032e4cd1cf499dd7c6c5cd1c1732c9f23f462"},{"code_id":"APK_RF","article_number":"229.6","version_date":"2002-07-24","article_text":"1. В судебном приказе указываются:\n\n1) номер дела и дата вынесения судебного приказа;\n\n2) наименование арбитражного суда, фамилия и инициалы судьи, вынесшего судебный приказ;\n\n3) сведения о взыскателе: для гражданина-взыскателя - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, серия и номер водительского удостоверения); для организации-взыскателя - наименование, адрес, идентификационный номер налогоплательщика; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n4) сведения о должнике, содержащиеся в заявлении о выдаче судебного приказа: для гражданина-должника - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, место работы (если известно), один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, основной государственный регистрационный номер индивидуального предпринимателя, серия и номер водительского удостоверения); для организации-должника - наименование, адрес, идентификационный номер налогоплательщика и основной государственный регистрационный номер; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n5) законы и иные нормативные правовые акты, которыми руководствовался суд при удовлетворении требования;\n\n6) размер денежных сумм, подлежащих взысканию;\n\n7) размер неустойки, если ее взыскание предусмотрено федеральным законом или договором, а также размер пеней, если таковые причитаются;\n\n8) сумма государственной пошлины, подлежащая взысканию с должника в пользу взыскателя или в доход соответствующего бюджета;\n\n9) реквизиты банковского счета взыскателя, на который должны быть перечислены средства, подлежащие взысканию, в случае, если обращение взыскания производится на средства бюджетов бюджетной системы Российской Федерации;\n\n10) период, за который образовалась взыскиваемая задолженность по обязательствам, предусматривающим исполнение по частям или в виде периодических платежей.\n\n(Наименование в редакции Федерального закона от 29.12.2015 № 409-ФЗ)\n\n(Параграф в редакции Федерального закона от 29.12.2015 № 409-ФЗ)","article_title":"Статья 229.6. Содержание судебного приказа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f843304c0e3ff439d6532942cb0372c4aeabb512f09ddf35668822db297e172f"},{"code_id":"APK_RF","article_number":"23","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\nОснованием для отвода эксперта является также проведение им ревизии или проверки, материалы которых стали поводом для обращения в арбитражный суд или используются при рассмотрении дела.","article_title":"Статья 23. Отвод помощника судьи, секретаря судебного заседания, эксперта, специалиста, переводчика","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5727f6a98ef2e99af7a4fb425e906446cc7d5b0fd7087b47761de28d34836102"},{"code_id":"APK_RF","article_number":"230","version_date":"2002-07-24","article_text":"1. Правила, установленные настоящим параграфом, применяются при рассмотрении арбитражным судом заявлений об оспаривании решений третейских судов и международных коммерческих арбитражей (третейских судов) с местом арбитража на территории Российской Федерации.\n\n2. Оспаривание в арбитражном суде решений третейских судов по спорам, возникающим из гражданских правоотношений при осуществлении предпринимательской и иной экономической деятельности, может быть осуществлено лицами, участвующими в третейском разбирательстве, а также иными лицами, в отношении прав и обязанностей которых вынесено решение третейского суда, путем подачи заявления в арбитражный суд об отмене решения третейского суда в соответствии со статьей 233 настоящего Кодекса.\n\n3. С заявлением об отмене решения третейского суда вправе обратиться прокурор по делам, предусмотренным абзацами третьим и четвертым части 1 статьи 52 настоящего Кодекса, если решение третейского суда затрагивает интересы Российской Федерации, субъекта Российской Федерации, муниципального образования, не участвовавших в третейском разбирательстве.\n\n4. Заявление об отмене решения третейского суда подается в арбитражный суд субъекта Российской Федерации, на территории которого принято решение третейского суда, в срок, не превышающий трех месяцев со дня получения оспариваемого решения стороной третейского разбирательства, обратившейся с заявлением, если иное не установлено международным договором Российской Федерации или федеральным законом. По соглашению сторон третейского разбирательства заявление об отмене решения третейского суда может быть подано в арбитражный суд субъекта Российской Федерации по месту нахождения одной из указанных сторон.\n\n5. Лицо, которое не является стороной третейского разбирательства и в отношении прав и обязанностей которого вынесено решение третейского суда, а также прокурор в случаях, установленных настоящей статьей, вправе подать заявление об отмене такого решения в арбитражный суд субъекта Российской Федерации, на территории которого принято решение третейского суда, в срок, не превышающий трех месяцев со дня, когда указанное лицо узнало или должно было узнать об оспариваемом им решении третейского суда.\n\n6. Заявление об отмене решения третейского суда оплачивается государственной пошлиной в размере, предусмотренном федеральным законом для оплаты заявления о выдаче исполнительного листа на принудительное исполнение решения третейского суда.","article_title":"Статья 230. Оспаривание решений третейских судов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"91bb80a9259832aff79d77c98046276e9cafb674f93e82a5b04bda4f27e6053e"},{"code_id":"APK_RF","article_number":"231","version_date":"2002-07-24","article_text":"1) наименование арбитражного суда, в который подается заявление;\n\n2) состав третейского суда, принявшего решение, его место нахождения, наименование постоянно действующего арбитражного учреждения, администрировавшего соответствующее третейское разбирательство, его место нахождения (в случае наличия постоянно действующего арбитражного учреждения);\n\n3) наименования сторон третейского разбирательства, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n4) дата и место принятия решения третейского суда;\n\n5) дата получения оспариваемого решения третейского суда стороной, обратившейся с заявлением об отмене указанного решения, либо дата, когда лицо, которое не является стороной третейского разбирательства и в отношении прав и обязанностей которого вынесено решение третейского суда, узнало об оспариваемом им решении;\n\n6) требование заявителя об отмене решения третейского суда, а также основания, по которым оспаривается указанное решение.\n\n1) копия решения третейского суда, подписанного арбитрами и направленного стороне третейского разбирательства в соответствии с федеральным законом;\n\n2) подлинное соглашение о третейском разбирательстве или его надлежащим образом заверенная копия;\n\n3) документы, представляемые в обоснование требования об отмене решения третейского суда;\n\n4) документ, подтверждающий уплату государственной пошлины в порядке и в размере, которые установлены федеральным законом;\n\n5) уведомление о вручении или иной документ, подтверждающий направление копии заявления об отмене решения третейского суда другой стороне третейского разбирательства;\n\n6) доверенность или иной документ, подтверждающие полномочия лица на подписание заявления.","article_title":"Статья 231. Требования к заявлению об отмене решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"84d48a7d25d684d76b685a99ade28164d4cde93897fc0a189a3fddcd0f43aff8"},{"code_id":"APK_RF","article_number":"232","version_date":"2002-07-24","article_text":"1. Заявление об отмене решения третейского суда рассматривается судьей единолично по правилам рассмотрения дела арбитражным судом первой инстанции, предусмотренным настоящим Кодексом, с учетом особенностей, установленных настоящим параграфом, в срок, не превышающий одного месяца со дня его поступления в ар\n\nбитражный суд субъекта Российской Федерации.\n\n2. При подготовке дела об отмене решения третейского суда к судебному разбирательству по ходатайству лиц, участвующих в деле, арбитражный суд может истребовать материалы дела, решение по которому оспаривается в арбитражном суде, из постоянно действующего арбитражного учреждения, в котором находятся на хранении материалы третейского дела, или из органа, уполномоченного на хранение материалов третейского дела в соответствии с законодательством Российской Федерации, по правилам, предусмотренным настоящим Кодексом для истребования доказательств.\n\n3. При рассмотрении заявления об отмене решения третейского суда, поданного лицом, которое не является стороной третейского разбирательства и в отношении прав и обязанностей которого вынесено решение третейского суда, арбитражный суд обязан привлечь к участию в деле все стороны третейского разбирательства.\n\n4. Лица, участвующие в деле об отмене решения третейского суда, извещаются арбитражным судом о времени и месте судебного заседания. Неявка указанных лиц, извещенных надлежащим образом о времени и месте проведения судебного заседания, не является препятствием для рассмотрения дела.\n\n5. Если заявление об отмене решения третейского суда подано по основаниям, связанным с тем, что сторона третейского разбирательства не была должным образом уведомлена о назначении третейского судьи или о третейском разбирательстве, в том числе о времени и месте заседания третейского суда, или по другим уважительным причинам не могла представить свои объяснения, либо что решение третейского суда вынесено по спору, не предусмотренному третейским соглашением или не подпадающему под его условия, или содержит постановления по вопросам, выходящим за пределы третейского соглашения, либо что состав третейского суда или арбитражная процедура не соответствовали соглашению сторон или федеральному закону, арбитражный суд по ходатайству стороны третейского разбирательства вправе приостановить производство по делу об отмене решения третейского суда на срок, не превышающий трех месяцев, с тем чтобы третейский суд возобновил третейское разбирательство и устранил основания для отмены арбитражного решения. После возобновления производства по делу об отмене решения третейского суда арбитражный суд рассматривает заявление об отмене решения третейского суда с учетом действий, предпринятых третейским судом в целях устранения оснований для отмены арбитражного решения.\n\n6. При рассмотрении дела арбитражный суд в судебном заседании устанавливает наличие или отсутствие оснований для отмены решения третейского суда, предусмотренных статьей 233 настоящего Кодекса, путем исследования представленных в суд доказательств в обоснование заявленных требований и возражений, но не вправе переоценивать обстоятельства, установленные третейским судом, либо пересматривать решение третейского суда по существу.","article_title":"Статья 232. Порядок рассмотрения заявления об отмене решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9d38d845307fc4d641bec8c84d1b4d8f5e6afd8b81ef6d072d46e108f524ae19"},{"code_id":"APK_RF","article_number":"233","version_date":"2002-07-24","article_text":"1. Решение третейского суда может быть отменено арбитражным судом только в случаях, предусмотренных настоящей статьей.\n\n2. Решение третейского суда может быть отменено арбитражным судом по основаниям, установленным частями 3 и 4 настоящей статьи. Решение третейского суда может быть отменено по основаниям, установленным частью 4 настоящей статьи, даже в том случае, если сторона, подавшая заявление об отмене такого решения, не ссылается на указанные основания.\n\n3. Решение третейского суда может быть отменено арбитражным судом лишь в случае, если сторона, подающая заявление об отмене такого решения, представит доказательства того, что:\n\n1) одна из сторон третейского соглашения, на основании которого спор был разрешен третейским судом, не обладала полной дееспособностью;\n\n2) третейское соглашение, на основании которого спор был разрешен третейским судом, недействительно по праву, которому стороны его подчинили, а при отсутствии такого указания - по праву Российской Федерации;\n\n3) решение третейского суда вынесено по спору, не предусмотренному третейским соглашением или не подпадающему под его условия, или содержит постановления по вопросам, выходящим за пределы третейского соглашения. Если постановления третейского суда по вопросам, которые охватываются третейским соглашением, могут быть отделены от постановлений по вопросам, которые не охватываются таким соглашением, может быть отменена только та часть решения, которая содержит постановления по вопросам, не охватываемым третейским соглашением;\n\n4) состав третейского суда или процедура арбитража не соответствовали соглашению сторон или федеральному закону;\n\n5) сторона, против которой принято решение третейского суда, не была должным образом уведомлена об избрании (назначении) третейских судей или о времени и месте заседания третейского суда либо по другим уважительным причинам не могла представить в третейский суд свои объяснения.\n\n4. Арбитражный суд отменяет решение третейского суда, если установит, что:\n\n1) спор, рассмотренный третейским судом, в соответствии с федеральным законом не может быть предметом третейского разбирательства;\n\n2) решение третейского суда противоречит публичному порядку Российской Федерации. Если часть решения третейского суда, которая противоречит публичному порядку Российской Федерации, может быть отделена от той части, которая ему не противоречит, может быть отменена только та часть решения третейского суда, которая противоречит публичному порядку Российской Федерации.\n\n5. Решение международного коммерческого арбитража может быть отменено арбитражным судом по основаниям, предусмотренным международным договором Российской Федерации и федеральным законом о международном коммерческом арбитраже.","article_title":"Статья 233. Основания для отмены решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"63b8331c9ad38813b4542def466cfd0a302e7709f3033e9c800dd21f43a8052f"},{"code_id":"APK_RF","article_number":"234","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения заявления об отмене решения третейского суда арбитражный суд выносит определение по правилам, установленным главой 20 настоящего Кодекса для принятия решения.\n\n2. В определении арбитражного суда по делу об оспаривании решения третейского суда должны содержаться:\n\n1) сведения об оспариваемом решении третейского суда и о месте его принятия;\n\n2) сведения о составе третейского суда, принявшего оспариваемое решение;\n\n3) наименования сторон третейского разбирательства;\n\n4) указание на отмену решения третейского суда полностью или в части либо отказ в удовлетворении требования заявителя полностью или в части;\n\n5) в случае отказа в удовлетворении требования заявителя об отмене решения третейского суда полностью или в части указание на возможность получения лицом, в пользу которого вынесено такое решение, исполнительного листа на принудительное исполнение решения третейского суда в порядке, предусмотренном статьей 319 настоящего Кодекса (за исключением случая, предусмотренного пунктом 3 части 7 статьи 238 настоящего Кодекса, если иным арбитражным судом Российской Федерации вынесено определение о выдаче исполнительного листа на принудительное исполнение того же решения третейского суда).\n\n3. Отмена решения третейского суда не препятствует сторонам третейского разбирательства повторно обратиться в третейский суд, если возможность обращения в третейский суд не утрачена, или в арбитражный суд по общим правилам, предусмотренным настоящим Кодексом.\n\n4. В случае, если решение третейского суда отменено арбитражным судом полностью или в части вследствие недействительности третейского соглашения, либо оно было принято по спору, не предусмотренному третейским соглашением или не подпадающему под его условия, либо содержит постановления по вопросам, не охватываемым третейским соглашением, а также если решение третейского суда отменено арбитражным судом в связи с тем, что спор, рассмотренный третейским судом, не может быть предметом третейского разбирательства в соответствии с федеральным законом или решение третейского суда нарушает публичный порядок Российской Федерации, стороны третейского разбирательства могут обратиться за разрешением такого спора в арбитражный суд по общим правилам, предусмотренным настоящим Кодексом.\n\n5. Определение арбитражного суда по делу об оспаривании решения третейского суда может быть обжаловано в кассационном порядке в арбитражный суд округа в течение одного месяца со дня вынесения определения.","article_title":"Статья 234. Определение арбитражного суда по делу об оспаривании решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c5f2439d2dcf6863e6566049a731114595695d1c387f136cf853d579428b726d"},{"code_id":"APK_RF","article_number":"235","version_date":"2002-07-24","article_text":"1. В случаях, предусмотренных федеральным законом, любая сторона третейского разбирательства может обратиться в арбитражный суд субъекта Российской Федерации, на территории которого проводится третейское разбирательство, с заявлением об отмене постановления третейского суда предварительного характера о наличии у него компетенции.\n\n2. Заявление по вопросу компетенции третейского суда может быть подано в течение одного месяца после получения стороной третейского разбирательства постановления третейского суда, указанного в части 1 настоящей статьи.\n\n3. Арбитражный суд рассматривает заявление по вопросу компетенции третейского суда по правилам, предусмотренным настоящим параграфом.\n\n4. Если к моменту рассмотрения арбитражным судом заявления по вопросу компетенции третейского суда будет вынесено решение третейского суда по тому же спору, указанное заявление подлежит оставлению без рассмотрения в связи с завершением третейского разбирательства. В этом случае сторона третейского разбирательства, подавшая заявление по вопросу компетенции третейского суда, не лишена права ссылаться на обстоятельства, являющиеся основанием для указанного заявления, при рассмотрении арбитражным судом заявления об отмене или о выдаче исполнительного листа на принудительное исполнение решения третейского суда по тому же спору.\n\n5. По результатам рассмотрения заявления по вопросу компетенции третейского суда арбитражный суд выносит определение об отмене постановления третейского суда о наличии у него компетенции или об отказе в удовлетворении требования заявителя.\n\n6. Определение арбитражного суда, указанное в части 5 настоящей статьи, не может быть обжаловано.\n\n(Параграф в редакции Федерального закона от 29.12.2015 № 409-ФЗ)","article_title":"Статья 235. Рассмотрение заявления по вопросу компетенции третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57fc99e2451f014722af4e14b4759449669a319d6eec939c512a5f2238b2e56f"},{"code_id":"APK_RF","article_number":"236","version_date":"2002-07-24","article_text":"1. Правила, установленные настоящим параграфом, применяются при рассмотрении арбитражным судом заявлений о выдаче исполнительных листов на принудительное исполнение принятых на территории Российской Федерации решений третейских судов и международных коммерческих арбитражей (третейских судов).\n\n2. Вопрос о выдаче исполнительного листа на принудительное исполнение решения третейского суда по спору, возникшему из гражданских правоотношений при осуществлении предпринимательской и иной экономической деятельности, рассматривается арбитражным судом по заявлению стороны третейского разбирательства, в пользу которой принято решение третейского суда.","article_title":"Статья 236. Выдача исполнительного листа на принудительное исполнение решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d659218c91f0e62b9e559fb5943a5e3d4a0aba84f879061f123af88f81a5fc34"},{"code_id":"APK_RF","article_number":"237","version_date":"2002-07-24","article_text":"1) наименование арбитражного суда, в который подается заявление;\n\n2) состав третейского суда, принявшего решение, его место нахождения, наименование постоянно действующего арбитражного учреждения, администрировавшего соответствующее третейское разбирательство, его место нахождения (в случае наличия постоянно действующего арбитражного учреждения);\n\n3) наименования сторон третейского разбирательства, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n4) дата и место принятия решения третейского суда;\n\n5) требование заявителя о выдаче исполнительного листа на принудительное исполнение решения третейского суда.\n\n1) копия подписанного арбитрами решения третейского суда, заверенная постоянно действующим арбитражным учреждением, нотариально удостоверенная копия решения третейского суда, образованного сторонами для разрешения конкретного спора;\n\n2) подлинное соглашение о третейском разбирательстве или его надлежащим образом заверенная копия;\n\n3) документ, подтверждающий уплату государственной пошлины в порядке и в размере, которые установлены федеральным законом;\n\n4) уведомление о вручении или иной документ, подтверждающие направление копии заявления о выдаче исполнительного листа на принудительное исполнение решения третейского суда другой стороне третейского разбирательства;\n\n5) доверенность или иной документ, подтверждающие полномочия лица на подписание заявления.","article_title":"Статья 237. Требования к заявлению о выдаче исполнительного листа на принудительное исполнение решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3cf1f998230411ab1518eb4b7be9652c38149f1bffcc699b50ca9a064087357b"},{"code_id":"APK_RF","article_number":"238","version_date":"2002-07-24","article_text":"1. Заявление о выдаче исполнительного листа на принудительное исполнение решения третейского суда рассматривается судьей единолично по правилам рассмотрения дела арбитражным судом первой инстанции, предусмотренным настоящим Кодексом, с учетом особенностей, установленных настоящим параграфом, в срок, не превышающий одного месяца со дня его поступления в арбитражный суд субъекта Российской Федерации.\n\n2. При подготовке дела к судебному разбирательству по ходатайству стороны третейского разбирательства суд может истребовать из постоянно действующего арбитражного учреждения или из органа, уполномоченного на хранение материалов третейского дела в соответствии с законодательством Российской Федерации, материалы дела, по которому испрашивается исполнительный лист на принудительное исполнение решения третейского суда, по правилам, предусмотренным настоящим Кодексом для истребования доказательств.\n\n3. Стороны третейского разбирательства извещаются арбитражным судом о времени и месте судебного заседания. Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения дела.\n\n4. При рассмотрении дела арбитражный суд в судебном заседании устанавливает наличие или отсутствие оснований для отказа в выдаче исполнительного листа на принудительное исполнение решения третейского суда, предусмотренных статьей 239 настоящего Кодекса, путем исследования представленных в суд доказательств обоснования заявленных требований и возражений, но не вправе переоценивать обстоятельства, установленные третейским судом, либо пересматривать решение третейского суда по существу.\n\n5. Если в одном и том же арбитражном суде находятся на рассмотрении заявление о выдаче исполнительного листа на принудительное исполнение решения третейского суда и заявление о его отмене, арбитражный суд объединяет указанные дела в одно производство в порядке, предусмотренном частями 21 и 6 статьи 130 настоящего Кодекса.\n\n6. Если в различных арбитражных судах Российской Федерации находятся на рассмотрении заявление о выдаче исполнительного листа на принудительное исполнение решения третейского суда и заявление о его отмене, арбитражный суд, в котором рассматривается то из указанных заявлений, которое было подано позднее, обязан приостановить возбужденное им производство в соответствии с пунктом 1 части 1 статьи 143 настоящего Кодекса до рассмотрения иным арбитражным судом того из указанных заявлений, которое было подано первым. В случае, если в различных арбитражных судах Российской Федерации находятся на рассмотрении поданные в один и тот же день заявление о выдаче исполнительного листа на принудительное исполнение решения третейского суда и заявление о его отмене, по правилам, установленным настоящей частью, подлежит приостановлению производство по делу о выдаче исполнительного листа на принудительное исполнение решения третейского суда.\n\n7. После возобновления производства по делу, которое было приостановлено в соответствии с положениями части 6 настоящей статьи, арбитражный суд выносит определение:\n\n1) об отказе в выдаче исполнительного листа на принудительное исполнение решения третейского суда в случае вынесения иным арбитражным судом Российской Федерации определения об отмене этого решения;\n\n2) о прекращении производства по заявлению о выдаче исполнительного листа на принудительное исполнение решения третейского суда в соответствии с пунктом 2 части 1 статьи 150 настоящего Кодекса в случае вынесения иным арбитражным судом Российской Федерации определения об отказе в отмене этого решения с учетом положений пункта 5 части 2 статьи 234 настоящего Кодекса;\n\n3) об отказе в отмене решения третейского суда в случае вынесения иным арбитражным судом Российской Федерации определения о выдаче исполнительного листа на принудительное исполнение этого решения;\n\n4) о прекращении производства по заявлению об отмене решения третейского суда по правилам, предусмотренным пунктом 2 части 1 статьи 150 настоящего Кодекса, в случае вынесения иным арбитражным судом Российской Федерации определения об отказе в выдаче исполнительного листа на принудительное исполнение этого решения.\n\n8. В случае, если арбитражный суд, рассматривающий заявление об отмене решения третейского суда или о приведении этого решения в исполнение, приостановит производство по делу, чтобы третейский суд возобновил третейско\n\nе разбирательство и устранил основания для отмены решения третейского суда или отказа в его принудительном исполнении, третейский суд может возобновить третейское разбирательство по ходатайству любой стороны, поданному в течение срока такого приостановления дела в арбитражном суде.","article_title":"Статья 238. Порядок рассмотрения заявлений о выдаче исполнительного листа на принудительное исполнение решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"81b4bd192547b32ee378ab47991cdd520c2988ac01d6526c82dd03a930aab1bd"},{"code_id":"APK_RF","article_number":"239","version_date":"2002-07-24","article_text":"1. Арбитражный суд может отказать в выдаче исполнительного листа на принудительное исполнение решения третейского суда только в случаях, предусмотренных настоящей статьей.\n\n2. В выдаче исполнительного листа на принудительное исполнение решения третейского суда может быть отказано по основаниям, установленным частями 3 и 4 настоящей статьи. В выдаче исполнительного листа на принудительное исполнение решения третейского суда может быть отказано по основаниям, установленным частью 4 настоящей статьи, даже в том случае, если сторона, против которой вынесено решение, не ссылается на указанные основания.\n\n3. Арбитражный суд может отказать в выдаче исполнительного листа на принудительное исполнение решения третейского суда, если сторона третейского разбирательства, против которой вынесено решение третейского суда, представит доказательства того, что:\n\n1) одна из сторон третейского соглашения, на основании которого спор разрешен третейским судом, не обладала полной дееспособностью;\n\n2) третейское соглашение, на основании которого спор был разрешен третейским судом, недействительно по праву, которому стороны его подчинили, а при отсутствии такого указания по праву Российской Федерации;\n\n3) сторона, против которой вынесено решение, не была должным образом уведомлена о назначении третейского судьи или о третейском разбирательстве, в том числе о времени и месте заседания третейского суда, либо по другим уважительным причинам не могла представить в третейский суд свои объяснения;\n\n4) решение третейского суда вынесено по спору, не предусмотренному третейским соглашением или не подпадающему под его условия, либо содержит постановления по вопросам, выходящим за пределы третейского соглашения, и что если постановления по вопросам, охватываемым третейским соглашением, могут быть отделены от тех, которые не охватываются таким соглашением, та часть решения третейского суда, в которой содержатся постановления по вопросам, охватываемым третейским соглашением, может быть признана и приведена в исполнение;\n\n5) состав третейского суда или процедура арбитража не соответствовали соглашению сторон или федеральному закону.\n\n4. Арбитражный суд отказывает в выдаче исполнительного листа на принудительное исполнение решения третейского суда, если установит, что:\n\n1) спор, рассмотренный третейским судом, в соответствии с федеральным законом не может быть предметом третейского разбирательства;\n\n2) приведение в исполнение решения третейского суда противоречит публичному порядку Российской Федерации. Если часть решения третейского суда, которая противоречит публичному порядку Российской Федерации, может быть отделена от той части, которая ему не противоречит, та часть решения, которая не противоречит публичному порядку Российской Федерации, может быть признана или приведена в исполнение.\n\n5. Арбитражный суд может отказать в выдаче исполнительного листа на принудительное исполнение решения международного коммерческого арбитража по основаниям, предусмотренным международным договором Российской Федерации и федеральным законом о международном коммерческом арбитраже.","article_title":"Статья 239. Основания отказа в выдаче исполнительного листа на принудительное исполнение решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b25208fc6d082f38c62517d8109c66d49d7d2db7481057d1a82f8c8ac0298183"},{"code_id":"APK_RF","article_number":"24","version_date":"2002-07-24","article_text":"В ходе рассмотрения дела заявление о самоотводе или об отводе допускается только в случае, если основание самоотвода или отвода стало известно лицу, заявляющему самоотвод или отвод, после начала рассмотрения дела по существу.","article_title":"Статья 24. Заявления о самоотводах и об отводах","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a7f6e22434f44b45f793513fb9306d7dbc9877f59e6fdf72690a3f4e227ac2ce"},{"code_id":"APK_RF","article_number":"240","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения заявления о выдаче исполнительного листа на принудительное исполнение решения третейского суда арбитражный суд выносит определение в порядке, установленном главой 20 настоящего Кодекса для принятия решения.\n\n2. В определении по делу о выдаче исполнительного листа на принудительное исполнение решения третейского суда должны содержаться:\n\n1) сведения о составе третейского суда, принявшего это решение;\n\n2) наименование постоянно действующего арбитражного учреждения, администрировавшего третейское разбирательство, его место нахождения (в случае наличия постоянно действующего арбитражного учреждения);\n\n3) наименования сторон третейского разбирательства;\n\n4) сведения о решении третейского суда, о выдаче исполнительного листа на принудительное исполнение которого ходатайствует заявитель;\n\n5) указание на выдачу исполнительного листа на принудительное исполнение решения третейского суда или отказ в выдаче исполнительного листа.\n\n3. Отказ в выдаче исполнительного листа на принудительное исполнение решения третейского суда не является препятствием для повторного обращения в третейский суд, если возможность обращения в третейский суд не утрачена, или в арбитражный суд по общим правилам, предусмотренным настоящим Кодексом.\n\n4. В случае, если в выдаче исполнительного листа на принудительное исполнение решения третейского суда отказано арбитражным судом полностью или в части вследствие недействительности соглашения о третейском разбирательстве либо решение было принято по спору, не предусмотренному третейским соглашением, или не подпадает под его условия, или содержит постановления по вопросам, не охватываемым соглашением о третейском разбирательстве, а также если спор, рассмотренный третейским судом, не может быть предметом третейского разбирательства в соответствии с федеральным законом или решение третейского суда противоречит публичному порядку Российской Федерации, стороны третейского разбирательства могут обратиться за разрешением такого спора в арбитражный суд по общим правилам, предусмотренным настоящим Кодексом.\n\n5. Определение арбитражного суда по делу о выдаче исполнительного листа на принудительное исполнение решения третейского суда может быть обжаловано в кассационном порядке в арбитражный суд округа в течение одного месяца со дня вынесения определения.\n\n(Дополнение параграфом - Федеральный закон от 29.12.2015 № 409-ФЗ)","article_title":"Статья 240. Определение арбитражного суда по делу о выдаче исполнительного листа на принудительное исполнение решения третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a94c97f165eecb438210bea0f43deecf6034bd0f453cc725eb784443d2701df4"},{"code_id":"APK_RF","article_number":"240.1","version_date":"2002-07-24","article_text":"1. Правила, установленные настоящим параграфом, применяются при осуществлении арбитражным судом функций содействия в отношении третейского разбирательства, осуществляемого на территории Российской Федерации.\n\n2. В соответствии с настоящим параграфом арбитражный суд осуществляет следующие функции содействия в отношении третейских судов по спорам, возникающим из гражданских правоотношений при осуществлении предпринимательской и иной экономической деятельности:\n\n1) разрешение вопросов, связанных с отводом третейского судьи;\n\n2) разрешение вопросов, связанных с назначением третейского судьи;\n\n3) разрешение вопросов, связанных с прекращением полномочий третейского судьи.\n\n3. Арбитражный суд осуществляет функции, указанные в части 2 настоящей статьи, только в случаях, предусмотренных федеральным законом.\n\n4. Арбитражный суд осуществляет функции, указанные в части 2 настоящей статьи, на основании заявления, поданного лицом или лицами, участвующими в третейском разбирательстве.\n\n5. Заявление, указанное в части 4 настоящей статьи, подается в арбитражный суд субъекта Российской Федерации, на территории которого проводится соответствующее третейское разбирательство, в срок, не превышающий одного месяца со дня, когда лицу, подающему заявление, стало известно или должно было стать известно об обстоятельствах, являющихся основанием для подачи заявления.\n\n6. Заявление, указанное в части 4 настоящей статьи, оплачивается государственной пошлиной в размере, предусмотренном федеральным законом для оплаты искового заявления неимущественного характера.","article_title":"Статья 240.1. Дела, связанные с выполнением арбитражными судами функций содействия в отношении третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"60bca7646c172e9a19e9ee237da28194fa4e0a55eae87e716dd50bab440a110f"},{"code_id":"APK_RF","article_number":"240.2","version_date":"2002-07-24","article_text":"1) наименование арбитражного суда, в который подается заявление о содействии;\n\n2) состав третейского суда, рассматривающего спор, его место нахождения, наименование постоянно действующего арбитражного учреждения, администрирующего третейское разбирательство, его место нахождения (в случае наличия постоянно действующего арбитражного учреждения);\n\n3) наименования сторон третейского разбирательства, их место нахождения или место жительства;\n\n4) сведения о третейском судье (третейских судьях), в отношении которого подается заявление о содействии (если применимо);\n\n5) указание на обстоятельства, являющиеся основанием для обращения заявителя в арбитражный суд за содействием в отношении третейского суда, а также на нормы федерального закона, предусматривающие выполнение арбитражным судом тех функций, за выполнением которых обращается заявитель;\n\n6) требование заявителя и основания требования.\n\n1) надлежащим образом заверенная копия искового заявления в третейский суд с доказательствами его получения ответчиком. Копии указанных документов могут быть заверены председателем постоянно действующего арбитражного учреждения, администрирующего соответствующее третейское разбирательство, или нотариально удостоверены;\n\n2) подлинное соглашение о третейском разбирательстве или его надлежащим образом заверенная копия;\n\n3) документы, подтверждающие обстоятельства, являющиеся основанием для обращения заявителя в арбитражный суд за содействием в отношении третейского суда;\n\n4) документы, представляемые в обоснование требования заявителя;\n\n5) документ, подтверждающий уплату государственной пошлины в порядке и в размере, которые установлены федеральным законом;\n\n6) доверенность или иной документ, подтверждающие полномочия лица на подписание заявления о содействии.","article_title":"Статья 240.2. Требования к заявлению о выполнении арбитражными судами функций содействия в отношении третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"16db74f2fae8ca357085a436663e3fb725f3c70e33f330f5bdf731b59f00fa29"},{"code_id":"APK_RF","article_number":"240.3","version_date":"2002-07-24","article_text":"1. Заявление о содействии рассматривается единолично судьей арбитражного суда субъекта Российской Федерации по правилам рассмотрения дела арбитражным судом первой инстанции, предусмотренным настоящим Кодексом, с особенностями, установленными настоящим параграфом и федеральным законом, в срок, не превышающий одного месяца со дня поступления заявления о содействии в арбитражный суд субъекта Российской Федерации.\n\n2. Стороны третейского разбирательства извещаются арбитражным судом о времени и месте судебного заседания. Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения дела.\n\n3. При рассмотрении дела арбитражный суд в судебном заседании устанавливает наличие или отсутствие оснований для удовлетворения требований заявителя путем исследования представленных в суд доказательств в обоснование заявленных требований и возражений.\n\n4. Если к моменту рассмотрения арбитражным судом заявления о содействии для решения вопроса, указанного в пункте 1 части 2 статьи 2401 настоящего Кодекса, будет вынесено решение третейского суда по соответствующему спору, заявление о содействии подлежит оставлению без рассмотрения в связи с завершением третейского разбирательства. В этом случае сторона третейского разбирательства, подавшая заявление о содействии, не лишена права ссылаться на обстоятельства, являющиеся основанием заявления о содействии, при рассмотрении арбитражным судом заявления об отмене или о выдаче исполнительного листа на принудительное исполнение решения третейского суда по тому же спору.\n\n5. Судья, выполнявший функции содействия в отношении третейского суда, указанные в части 2 статьи 2401 настоящего Кодекса, не вправе участвовать в рассмотрении заявления об отмене или о выдаче исполнительного листа на принудительное исполнение решения третейского суда по соответствующему спору в соответствии с пунктом 1 части 1 статьи 21 настоящего Кодекса.","article_title":"Статья 240.3. Порядок рассмотрения заявления о содействии","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b131b83d346a54f510819318f7f9ffe9550594715a8abd73f6a9ccb039ef62d2"},{"code_id":"APK_RF","article_number":"240.4","version_date":"2002-07-24","article_text":"1. Заявление по вопросу об отводе третейского судьи подлежит удовлетворению арбитражным судом при наличии одновременно следующих обстоятельств:\n\n1) соблюдена процедура отвода третейского судьи, которая установлена сторонами или федеральным законом и согласно которой вопрос об отводе третейского судьи передан на разрешение арбитражного суда;\n\n2) имеются основания для отвода третейского судьи, установленные федеральным законом.\n\n2. Заявление по вопросу о назначении третейского судьи подлежит удовлетворению арбитражным судом при наличии одновременно следующих обстоятельств:\n\n1) соблюдена процедура назначения третейского судьи, которая установлена сторонами или федеральным законом и согласно которой вопрос о назначении третейского судьи передан на разрешение арбитражного суда;\n\n2) в соответствии с федеральным законом арбитражный суд полномочен решить вопрос, связанный с назначением третейского судьи.\n\n3. Заявление по вопросу о прекращении полномочий третейского судьи подлежит удовлетворению арбитражным судом при наличии одновременно следующих обстоятельств:\n\n1) соблюдена процедура прекращения полномочий третейского судьи, которая установлена сторонами или федеральным законом и согласно которой вопрос о прекращении полномочий третейского судьи передан на разрешение арбитражного суда;\n\n2) имеются основания для прекращения полномочий третейского судьи, предусмотренные федеральным законом.","article_title":"Статья 240.4. Основания для удовлетворения заявления о содействии","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4403a05e20baf2305b8b0971ad679d326352c56bfff63faa3d5357b8333eb849"},{"code_id":"APK_RF","article_number":"240.5","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения заявления о содействии арбитражный суд выносит определение по правилам, установленным главой 21 настоящего Кодекса для вынесения определения.\n\n2. В определении арбитражного суда по делу о выполнении арбитражными судами функций содействия в отношении третейских судов должны содержаться:\n\n1) наименование постоянно действующего арбитражного учреждения, администрирующего третейское разбирательство, его место нахождения (в случае наличия постоянно действующего арбитражного учреждения);\n\n2) сведения о составе третейского суда, рассматривающего спор, его месте нахождения;\n\n3) наименования сторон третейского разбирательства;\n\n4) изложение обстоятельств, являющихся основанием для обращения заявителя в арбитражный суд за содействием в отношении третейского суда, а также указание на нормы федерального закона, предусматривающие выполнение арбитражным судом тех функций, за выполнением которых обращается заявитель;\n\n5) указание на удовлетворение требований заявителя полностью или в части либо отказ в удовлетворении требований заявителя полностью или в части с указанием мотивов, по которым арбитражный суд удовлетворил требования заявителя или отказал в их удовлетворении;\n\n6) в случае удовлетворения требований заявителя сведения о третейском судье (третейских судьях), вопросы об отводе, о назначении или прекращении полномочий которого разрешены.\n\n3. Определение арбитражного суда по делу о выполнении арбитражными судами функций содействия в отношении третейского суда не может быть обжаловано.","article_title":"Статья 240.5. Определение арбитражного суда по делу о выполнении арбитражными судами функций содействия в отношении третейских судов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"91e179d2e476e6f070d52b7d6bd00486c0393dd5c0dd013b5919b8e448798cf6"},{"code_id":"APK_RF","article_number":"241","version_date":"2002-07-24","article_text":"1. Решения судов иностранных государств, принятые ими по спорам и иным делам, возникающим при осуществлении предпринимательской и иной экономической деятельности (иностранные суды), решения третейских судов и международных коммерческих арбитражей, принятые ими на территориях иностранных государств по спорам и иным делам, возникающим при осуществлении предпринимательской и иной экономической деятельности (иностранные арбитражные решения), признаются и приводятся в исполнение в Российской Федерации арбитражными судами, если признание и приведение в исполнение таких решений предусмотрено международным договором Российской Федерации и федеральным законом.\n\n2. Вопросы признания и приведения в исполнение решения иностранного суда и иностранного арбитражного решения разрешаются арбитражным судом по заявлению стороны в споре, рассмотренном иностранным судом, или стороны третейского разбирательства.","article_title":"Статья 241. Признание и приведение в исполнение решений иностранных судов и иностранных арбитражных решений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"27b9336be0f68cbb03cddfae260525e4b880f6565bd8e5a2f454633232d30ebd"},{"code_id":"APK_RF","article_number":"242","version_date":"2002-07-24","article_text":"В заявлении должны быть указаны:\n\n1) наименование арбитражного суда, в который подается заявление;\n\n2) наименование и место нахождения иностранного суда либо наименование и состав третейского суда или международного коммерческого арбитража, место его нахождения;\n\n3) наименование взыскателя, его место нахождения или место жительства;\n\n4) наименование должника, его место нахождения или место жительства;\n\n5) сведения о решении иностранного суда или об иностранном арбитражном решении, о признании и приведении в исполнение которых ходатайствует взыскатель;\n\n6) ходатайство взыскателя о признании и приведении в исполнение решения иностранного суда или иностранного арбитражного решения;\n\n7) перечень прилагаемых документов.\n\nВ заявлении о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения могут быть также указаны номера телефонов, факсов, адреса электронной почты взыскателя, должника, их представителей и иные сведения.\n\n1) удостоверенная надлежащим образом копия решения иностранного суда или иностранного арбитражного решения, о признании и приведении в исполнение которых ходатайствует взыскатель;\n\n2) документ, удостоверенный надлежащим образом и подтверждающий вступление решения иностранного суда в законную силу, если это не указано в тексте самого решения;\n\n3) документ, удостоверенный надлежащим образом и подтверждающий, что должник был своевременно и в надлежащей форме извещен о разбирательстве дела в иностранном суде, о признании и приведении в исполнение решения которого ходатайствует взыскатель;\n\n4) доверенность или иной документ, удостоверенные надлежащим образом и подтверждающие полномочия лица, подписавшего заявление в арбитражный суд;\n\n5) документ, подтверждающий направление должнику копии заявления о признании и приведении в исполнение решения иностранного суда;\n\n6) заверенный надлежащим образом перевод указанных в пунктах 1 - 5 настоящей части документов на русский язык.\n\n1) надлежащим образом заверенное подлинное иностранное арбитражное решение или его надлежащим образом заверенная копия;\n\n2) подлинное соглашение о третейском разбирательстве или его надлежащим образом заверенная копия;\n\n3) надлежащим образом заверенный перевод на русский язык документов, указанных в пунктах 1 и 2 настоящей части.","article_title":"Статья 242. Заявление о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"adecce77c95d08acb69b1b9d4a45d76d573b399569ec8decf34e3eb7f2967e4f"},{"code_id":"APK_RF","article_number":"243","version_date":"2002-07-24","article_text":"1. Заявление о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения рассматривается судьей единолично по правилам рассмотрения дела арбитражным судом первой инстанции, предусмотренным настоящим Кодексом, с учетом особенностей, установленных настоящей главой, в срок, не превышающий одного месяца со дня его поступления в арбитражный суд субъекта Российской Федерации.\n\n2. Арбитражный суд извещает лиц, участвующих в деле, о времени и месте судебного заседания. Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения дела.\n\n3. При рассмотрении дела арбитражный суд в судебном заседании устанавливает наличие или отсутствие оснований для признания и приведения в исполнение решения иностранного суда и иностранного арбитражного решения, предусмотренных статьей 244 настоящего Кодекса, путем исследования представленных в арбитражный суд доказательств, обоснования заявленных требований и возражений, а также разъяснений иностранного суда или третейского суда, принявших решение, если арбитражный суд истребует такие разъяснения.\n\n4. При рассмотрении дела арбитражный суд не вправе пересматривать решение иностранного суда по существу.\n\n5. Если в иностранном суде находится на рассмотрении заявление об отмене или о приостановлении исполнения решения иностранного суда и иностранного арбитражного решения, арбитражный суд, в котором рассматривается заявление о признании и приведении в исполнение этого решения, может по ходатайству одной из сторон отложить рассмотрение заявления о выдаче исполнительного листа.\n\n6. В случае, указанном в части 5 настоящей статьи, арбитражный суд, в котором рассматривается заявление о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения, по ходатайству стороны, обратившейся с таким заявлением, может обязать другую сторону предоставить надлежащее обеспечение по правилам, предусмотренным настоящим Кодексом.\n\n7. Если в случае, указанном в части 5 настоящей статьи, рассмотрение заявления о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения было отложено арбитражным судом, после разрешения иностранным судом заявления об отмене или о приостановлении исполнения решения иностранного суда и иностранного арбитражного решения арбитражный суд, в котором рассматривается заявление о признании и приведении в исполнение этого решения, рассматривает заявление о признании и приведении в исполнение этого решения с учетом вынесенного иностранным судом судебного акта в соответствии с международными договорами Российской Федерации и федеральными законами.\n\n(Статья в редакции Федерального закона от 29.12.2015 № 409-ФЗ)","article_title":"Статья 243. Порядок рассмотрения заявления о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7f594a489b6ad033b8a44a94781bde76c1f744a1b933997285dccdc807a8ece6"},{"code_id":"APK_RF","article_number":"244","version_date":"2002-07-24","article_text":"1. Арбитражный суд отказывает в признании и приведении в исполнение решения иностранного суда полностью или в части в случае, если:\n\n1) решение по закону государства, на территории которого оно принято, не вступило в законную силу;\n\n2) сторона, против которой принято решение, не была своевременно и надлежащим образом извещена о времени и месте рассмотрения дела или по другим причинам не могла представить в суд свои объяснения;\n\n3) рассмотрение дела в соответствии с международным договором Российской Федерации или федеральным законом относится к исключительной компетенции суда в Российской Федерации, за исключением случаев, указанных в части 5 статьи 2481 настоящего Кодекса; (В редакции Федерального закона от 08.06.2020 № 171-ФЗ)\n\n4) имеется вступившее в законную силу решение суда в Российской Федерации, принятое по спору между теми же лицами, о том же предмете и по тем же основаниям;\n\n5) на рассмотрении суда в Российской Федерации находится дело по спору между теми же лицами, о том же предмете и по тем же основаниям, производство по которому возбуждено до возбуждения производства по делу в иностранном суде, или суд в Российской Федерации первым принял к своему производству заявление по спору между теми же лицами, о том же предмете и по тем же основаниям;\n\n6) истек срок давности приведения решения иностранного суда к принудительному исполнению и этот срок не восстановлен арбитражным судом;\n\n7) исполнение решения иностранного суда противоречило бы публичному порядку Российской Федерации.","article_title":"Статья 244. Основания отказа в признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"974e5ae2e41dd57ee7a7c05aff99eb114705f4da4cae358f3b9ad90e10341615"},{"code_id":"APK_RF","article_number":"245","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения заявления о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения арбитражный суд выносит определение по правилам, установленным в главе 20 настоящего Кодекса для принятия решения.\n\n2. В определении по делу о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения должны содержаться:\n\n1) наименование и место нахождения иностранного суда либо наименование и состав третейского суда или международного коммерческого арбитража, принявших решение;\n\n2) наименования взыскателя и должника;\n\n3) сведения о решении иностранного суда или об иностранном арбитражном решении, о признании и приведении в исполнение которого ходатайствовал взыскатель;\n\n4) указание на признание и приведение в исполнение решения иностранного суда или иностранного арбитражного решения либо на отказ в признании и приведении в исполнение решения иностранного суда или иностранного арбитражного решения.","article_title":"Статья 245. Определение арбитражного суда по делу о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9ae0c8bc65b0bffee41412dcb9e7b2e4c53aa94cba47bd8c84cd823ddb694394"}]$law7d0005$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
